// ============================================================================
// pump_cores.h - intake (Issue #1), chemical dosing (Issue #3) and delivery
// (Issue #8) pump logic for Water Rover v2.
//
// Pure C++11, no Arduino calls: time is passed in as `nowMs`. The same code is
// used by waterdroid_esp32.ino, by the XOD C++ nodes in xod/waterdroid/ and by
// the host unit tests in firmware/tests, so behaviour is identical everywhere.
//
// None of these classes touch a relay directly. Each one raises `want`, the
// PowerSequencer (power_core.h) decides when the relay actually closes, and the
// caller feeds the real relay state back in as `relayOn`. That way a pump that
// is held off by the brownout guard never "counts" volume it did not pump.
// ============================================================================

#include <stdint.h>

static inline uint32_t pc_since(uint32_t now, uint32_t t) { return now - t; }  // wrap-safe

// ---------------------------------------------------------------------------
// Issue #1 - Intake & raw water collection
//   5 V submersible pump + coarse mesh pre-filter + 40-50 cm hose -> Stage 1.
//   * runs until Stage 1 is full (or the batch is complete)
//   * hard max-run cutoff so the pump motor cannot burn out
//   * dry-run protection: if the Stage 1 level does not rise while the relay is
//     ON, the intake is not in water -> stop and latch a DRY_RUN fault
//   * blocked while the filtration column overflows (Issue #5 interlock)
// ---------------------------------------------------------------------------
enum IntakeState : uint8_t { IN_IDLE = 0, IN_PUMPING, IN_FULL, IN_BLOCKED, IN_FAULT_DRY, IN_FAULT_TIMEOUT };

struct IntakeConfig {
  uint32_t maxRunMs   = 90000;   // motor-burnout cutoff
  uint32_t dryCheckMs = 8000;    // relay ON this long ...
  float    minRisePct = 2.0f;    // ... and Stage 1 rose less than this -> DRY_RUN
  float    fullPct    = 95.0f;   // Stage 1 full
};

struct IntakeController {
  IntakeConfig cfg;
  // outputs
  bool        want = false;
  IntakeState state = IN_IDLE;
  uint32_t    runMs = 0;          // relay-ON time of the current fill
  // internal
  bool     requested = false;
  bool     timing = false;
  uint32_t lastMs = 0;
  uint32_t dryWinMs = 0;
  float    dryRef = 0.0f;

  void start() {
    requested = true; runMs = 0; dryWinMs = 0; timing = false;
    if (state == IN_FAULT_DRY || state == IN_FAULT_TIMEOUT || state == IN_FULL) state = IN_IDLE;
  }
  void stop()  { requested = false; want = false; if (state == IN_PUMPING || state == IN_BLOCKED) state = IN_IDLE; }
  void clearFault() { if (state == IN_FAULT_DRY || state == IN_FAULT_TIMEOUT) state = IN_IDLE; }

  // levelPct: Stage 1 level, blocked: column overflow / e-stop / batch full
  void tick(uint32_t now, bool relayOn, float levelPct, bool blocked) {
    uint32_t dt = timing ? pc_since(now, lastMs) : 0;
    lastMs = now; timing = true;

    if (state == IN_FAULT_DRY || state == IN_FAULT_TIMEOUT) { want = false; requested = false; return; }
    if (!requested) { want = false; if (state != IN_FULL) state = IN_IDLE; return; }
    if (levelPct >= cfg.fullPct) { requested = false; want = false; state = IN_FULL; return; }
    if (blocked) { want = false; state = IN_BLOCKED; return; }

    want = true;
    state = IN_PUMPING;
    if (!relayOn) { dryWinMs = 0; dryRef = levelPct; return; }   // waiting for the power sequencer

    runMs += dt;
    if (dryWinMs == 0) dryRef = levelPct;
    dryWinMs += dt;
    if (dryWinMs >= cfg.dryCheckMs) {
      if (levelPct - dryRef < cfg.minRisePct) { want = false; requested = false; state = IN_FAULT_DRY; return; }
      dryWinMs = 0;
    }
    if (runMs >= cfg.maxRunMs) { want = false; requested = false; state = IN_FAULT_TIMEOUT; }
  }

  static const char* name(IntakeState s) {
    switch (s) {
      case IN_PUMPING: return "PUMPING";       case IN_FULL: return "FULL";
      case IN_BLOCKED: return "BLOCKED";       case IN_FAULT_DRY: return "DRY_RUN";
      case IN_FAULT_TIMEOUT: return "TIMEOUT"; default: return "IDLE";
    }
  }
};

// ---------------------------------------------------------------------------
// Issue #3 - Chemical dosing (chlorine -> Stage 3). Also used as the volumetric TRANSFER pump
//   (column -> delivery tank): same maths, volume = rate x relay-ON time.
//   Peristaltic pumps are volumetric: volume = rate x ON-time (2 s = 2 mL at
//   1 mL/s). ON-time is only counted while the relay is really closed.
// ---------------------------------------------------------------------------
struct DosingPump {
  float    rateMlPerS = 1.0f;     // calibrate: run 60 s into a measuring cylinder
  float    maxDoseMl  = 10.0f;    // safety ceiling per injection
  float    stockMl    = 250.0f;   // reservoir left (refill -> setStock)
  // outputs
  bool     want = false;
  float    totalMl = 0.0f;        // injected since boot (dashboard counter)
  float    lastDoseMl = 0.0f;
  // internal
  float    targetMl = 0.0f;
  float    doneMl = 0.0f;
  bool     timing = false;
  uint32_t lastMs = 0;

  // returns the dose actually accepted (clamped by maxDoseMl and stock)
  float start(float ml) {
    if (ml < 0) ml = 0;
    if (ml > maxDoseMl) ml = maxDoseMl;
    if (ml > stockMl) ml = stockMl;
    targetMl = ml; doneMl = 0.0f; want = ml > 0.0f;
    return ml;
  }
  void abort() { if (want) lastDoseMl = doneMl; want = false; targetMl = doneMl; }
  bool busy() const { return want; }
  float remainingMl() const { return targetMl - doneMl; }
  void setStock(float ml) { stockMl = ml; }

  // Auto dose for a water volume: mL of stock = litres x ratio
  static float doseFor(float waterMl, float mlPerLitre) { return waterMl / 1000.0f * mlPerLitre; }

  void tick(uint32_t now, bool relayOn) {
    uint32_t dt = timing ? pc_since(now, lastMs) : 0;
    lastMs = now; timing = true;
    if (!want) return;
    if (relayOn) {
      float d = rateMlPerS * dt / 1000.0f;
      if (d > targetMl - doneMl) d = targetMl - doneMl;
      doneMl += d; totalMl += d; stockMl -= d;
    }
    if (doneMl >= targetMl - 1e-4f || stockMl <= 0.0f) { want = false; lastDoseMl = doneMl; }
  }
};

// ---------------------------------------------------------------------------
// Issue #8 - Clean water storage & delivery
//   Delivery pump (Stage 3 -> container) only runs when the rover is at a
//   homestead (`armDeployed` stays true: the nozzle is fixed on this build). Volume = flow x ON-time.
// ---------------------------------------------------------------------------
enum DeliveryState : uint8_t { DL_IDLE = 0, DL_WAIT_ARM, DL_PUMPING, DL_DONE, DL_ABORTED };

struct DeliveryController {
  float    flowMlPerS  = 25.0f;   // calibrate with a measuring jug
  float    minCleanPct = 3.0f;    // stop before the pump runs dry
  uint32_t maxRunMs    = 60000;
  // outputs
  bool          want = false;
  DeliveryState state = DL_IDLE;
  float         deliveredMl = 0.0f;      // this delivery
  float         totalMl = 0.0f;          // since boot
  uint16_t      count = 0;
  const char*   reason = "";
  // internal
  float    targetMl = 0.0f;
  uint32_t runMs = 0;
  bool     timing = false;
  uint32_t lastMs = 0;

  void request(float ml) { targetMl = ml; deliveredMl = 0; runMs = 0; reason = ""; state = DL_WAIT_ARM; }
  void abort(const char* why) { if (state == DL_WAIT_ARM || state == DL_PUMPING) finish(DL_ABORTED, why); }

  void tick(uint32_t now, bool relayOn, bool atHomestead, bool armDeployed, float cleanPct) {
    uint32_t dt = timing ? pc_since(now, lastMs) : 0;
    lastMs = now; timing = true;
    if (state != DL_WAIT_ARM && state != DL_PUMPING) { want = false; return; }
    if (!atHomestead) { finish(DL_ABORTED, "not at homestead"); return; }
    if (cleanPct <= minCleanPct) { finish(deliveredMl > 0 ? DL_DONE : DL_ABORTED, "clean tank empty"); return; }
    if (!armDeployed) {
      if (state == DL_PUMPING) { finish(DL_ABORTED, "arm left deploy position"); return; }
      want = false; return;                  // still waiting for the arm
    }
    state = DL_PUMPING;
    want = true;
    if (relayOn) {
      float d = flowMlPerS * dt / 1000.0f;
      if (d > targetMl - deliveredMl) d = targetMl - deliveredMl;
      deliveredMl += d; totalMl += d; runMs += dt;
    }
    if (deliveredMl >= targetMl - 0.01f) finish(DL_DONE, "");
    else if (runMs >= maxRunMs) finish(DL_DONE, "max run time");
  }

  static const char* name(DeliveryState s) {
    switch (s) {
      case DL_WAIT_ARM: return "WAIT_ARM"; case DL_PUMPING: return "PUMPING";
      case DL_DONE: return "DONE";         case DL_ABORTED: return "ABORTED";
      default: return "IDLE";
    }
  }

 private:
  void finish(DeliveryState s, const char* why) {
    want = false; state = s; reason = why;
    if (s == DL_DONE) count++;
  }
};


